                    style={additionalStyles.currencyInput}
                    value={String(editedInventory.currency[currency] || 0)}
                    onChangeText={(text) => {
                      const value = parseInt(text) || 0;
                      setEditedInventory(prev => ({
                        ...prev,
                        currency: {
                          ...prev.currency,
                          [currency]: value
                        }
                      }));
                    }}
                    keyboardType="numeric"
                    placeholderTextColor={THEME.text.light + '80'}
