      {/* Room Modal */}
      <RoomModal
        visible={showRoomModal}
        setShowRoomModal={setShowRoomModal}
        isConnected={isConnected}
        roomCode={roomCode}
        setRoomCode={setRoomCode}
        isJoining={isJoining}
        connectToRoom={() => {
          setIsJoining(true);

          // Set up Firebase reference
          const roomRef = ref(database, `rooms/${roomCode}`);
          firebaseRef.current = roomRef;

          // Load existing data
          get(roomRef).then((snapshot) => {
            if (snapshot.exists()) {
              const data = snapshot.val();
              if (data.characters) {
                setCharacters(Object.values(data.characters));
              }
              if (data.tokens) {
                setTokens(data.tokens);
              }
            }

            // Set up real-time listeners
            onValue(roomRef, (snapshot) => {
              if (snapshot.exists()) {
                const data = snapshot.val();
                if (data.characters) {
                  setCharacters(Object.values(data.characters));
                }
                if (data.tokens) {
                  setTokens(data.tokens);
                }
              }
            });

            setIsConnected(true);
            setShowRoomModal(false);
            setIsJoining(false);
          }).catch((error) => {
            console.error("Error connecting to room:", error);
            Alert.alert("Error", "Failed to connect to room");
            setIsJoining(false);
          });
        }}
        THEME={THEME}
      />

      {/* Character Sheet Modal */}
      <CharacterSheetModal
        visible={showCharacterSheet}
        onClose={() => {
          setShowCharacterSheet(false);
          setSelectedCharacter(null);
        }}
        character={selectedCharacter}
        characters={characters}
        onUpdate={(updatedCharacter) => {
          // Generate a unique ID if this is a new character
          const characterId = updatedCharacter.id || generateUniqueId();

          const finalCharacter = {
            ...updatedCharacter,
            id: characterId,
            owner: updatedCharacter.id ? selectedCharacter.owner : playerName,
            createdAt: updatedCharacter.id ? selectedCharacter.createdAt : Date.now()
          };

          // Update local state
          setCharacters(prev => {
            const existingIndex = prev.findIndex(c => c.id === characterId);
            if (existingIndex >= 0) {
              // Update existing character
              return prev.map(c => c.id === characterId ? finalCharacter : c);
            } else {
              // Add new character
              return [...prev, finalCharacter];
            }
          });

          // Update Firebase
          if (firebaseRef.current) {
            const characterRef = ref(database, `rooms/${roomCode}/characters/${characterId}`);
            set(characterRef, finalCharacter);
          }

          setShowCharacterSheet(false);
          setSelectedCharacter(null);
        }}
        playerName={playerName}
        THEME={THEME}
      />
    </SafeAreaView>
  );
};

App.displayName = 'App';

export default App;
